def window_sums(nums, w):
    # window_sums([1, 2, 3, 4], 2) -> [3, 5, 7]
    sums = []
    for start in range(len(nums) - w):
        sums.append(sum(nums[start:start + w]))
    return sums

solution:
def window_sums(nums, w):
    sums = []
    for start in range(len(nums) - w + 1):
        sums.append(sum(nums[start:start + w]))
    return sums
